import React from 'react';
import { listings } from '../../list';

export default function FeaturedListings({ searchQuery, searchCategory }) {
  const filteredListings = Object.entries(listings)
    .flatMap(([category, categoryListings]) =>
      // Check if the category matches or if it's set to "All"
      (searchCategory === 'All' || category === searchCategory) 
        ? categoryListings 
        : []
    )
    .filter((listing) => {
      // Check if the listing matches the search query
      return searchQuery 
        ? listing.title.toLowerCase().includes(searchQuery.toLowerCase()) 
        : true;
    });

  return (
    <section className="container mx-auto px-4 py-8">
      <h2 className="text-xl md:text-2xl font-bold mb-6">Featured Listings</h2>
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        {filteredListings.map((listing) => (
          <div
            key={listing.id}
            className="bg-white rounded-lg shadow-md overflow-hidden hover:shadow-lg transition-shadow relative"
          >
            <img
              src={listing.image}
              alt={listing.title}
              width={300}
              height={200}
              className="w-full h-56 object-cover"
            />
            <div className="p-4">
              <h3 className="font-semibold mb-1 text-sm md:text-base truncate">{listing.title}</h3>
              <p className="text-red-600 font-bold text-lg">{listing.price}</p>
              <div className="text-gray-600 text-xs md:text-sm mt-2">
                <span className="bg-gray-200 rounded-full px-2 py-1 text-gray-700 mr-2">
                  {listing.condition}
                </span>
                <span>{listing.year}</span>
              </div>
              <p className="text-gray-500 text-xs mt-1">
                {listing.location} · {listing.added}
              </p>
            </div>
          </div>
        ))}
      </div>
    </section>
  );
}
